const input = $json;

// IGNORAR mensajes enviados por bots (evita loops)
if (input.message && input.message.from && input.message.from.is_bot === true) {
  return {
    json: {
      traceId: 'ignored-' + Date.now(),
      timestamp: new Date().toISOString(),
      channel: 'ignored',
      sender: 'ignored',
      message: '',
      manager: { workflow: 'WF_MANAGER_ORQUESTADOR', version: '1.0' },
      _skip: true
    }
  };
}

// Detección de origen
const esTelegram = input.message && input.message.chat && input.message.text;
const esChatTrigger = input.chatInput;
// ... el resto igual

let message, channel, sender;

if (esTelegram) {
  // Telegram: { message: { text, chat: { id }, from: { ... } } }
  message = input.message.text;
  channel = 'telegram';
  sender = String(input.message.chat.id);
} else if (esChatTrigger) {
  // Chat de n8n
  message = input.chatInput;
  channel = 'chat';
  sender = input.sessionId ?? 'chat-user';
} else {
  // Webhook genérico
  const data = input.body ?? input;
  message = data.message ?? data.text ?? '';
  channel = data.channel ?? 'unknown';
  sender = data.sender ?? data.from ?? 'unknown';
}

message = String(message).trim();

const traceId = `${Date.now()}-${Math.random().toString(36).substring(2, 10)}`;

return {
  json: {
    traceId,
    timestamp: new Date().toISOString(),

    channel,
    sender,
    message,

    manager: {
      workflow: 'WF_MANAGER_ORQUESTADOR',
      version: '1.0'
    }
  }
};

const allowedIntents = [
  'DISPONIBILIDAD',
  'RESERVA',
  'FACTURA_PAGO',
  'ATENCION_HUESPED'
];

// Con Output Parser, el resultado viene en $json.output (objeto)
const out = $json.output ?? {};

let intent = String(out.intent ?? '').trim().toUpperCase();
let confidence = Number(out.confidence ?? 0);

let payload = {
  fecha_inicio: out.payload?.fecha_inicio ?? null,
  fecha_fin: out.payload?.fecha_fin ?? null
};

// Validaciones de seguridad
let finalIntent = intent;
let fallbackApplied = false;

if (!allowedIntents.includes(intent)) {
  finalIntent = 'ATENCION_HUESPED';
  fallbackApplied = true;
}

if (!Number.isFinite(confidence) || confidence < 0.80) {
  finalIntent = 'ATENCION_HUESPED';
  fallbackApplied = true;
}

// Solo DISPONIBILIDAD y RESERVA conservan fechas
if (finalIntent !== 'DISPONIBILIDAD' && finalIntent !== 'RESERVA') {
  payload = { fecha_inicio: null, fecha_fin: null };
}

// Recuperar datos del nodo 03 (traceId, canal, etc.)
const base = $('03 - Normalizar + TraceID').first().json;

return {
  json: {
    traceId: base.traceId,
    timestamp: base.timestamp,
    channel: base.channel,
    sender: base.sender,
    message: base.message,

    intent: finalIntent,
    payload,

    triage: {
      originalIntent: intent,
      confidence,
      fallbackApplied
    }
  }
};

// 05b - Extraer Fechas + Categoria + Ocupacion + Pasajero (Manager)

const validado = $json;
const originalMessage = String(validado.message ?? '');  // sin tocar (para nombre)
const message = originalMessage
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, ''); // quita tildes
const timestamp = validado.timestamp;

// ---------- Utilidades ----------
const TZ_OFFSET_MS = 3 * 60 * 60 * 1000; // UTC-3
const MS_DAY = 24 * 60 * 60 * 1000;
const pad = (n) => String(n).padStart(2, '0');
const toISO = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;

const hoyISO = () => {
  const d = new Date(new Date(timestamp).getTime() - TZ_OFFSET_MS);
  return d.toISOString().slice(0, 10);
};

const addDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const diffDays = (a, b) =>
  Math.round(
    (new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / MS_DAY
  );

const DIAS = {
  domingo: 0, lunes: 1, martes: 2, miercoles: 3,
  jueves: 4, viernes: 5, sabado: 6
};

const MESES = {
  enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6,
  julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10,
  noviembre: 11, diciembre: 12
};

const ANIO_ACTUAL = parseInt(hoyISO().slice(0, 4), 10);

// ---------- Parsers de fecha ----------
const parseISO = (s) => {
  const m = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m ? toISO(m[1], m[2], m[3]) : null;
};

const parseSlash = (s) => {
  const m = s.match(/(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?/);
  if (!m) return null;
  let yy = m[3] ?? String(ANIO_ACTUAL);
  if (yy.length === 2) yy = '20' + yy;
  return toISO(yy, m[2], m[1]);
};

const parseMesNombre = (s) => {
  const m1 = s.match(/(\d{1,2})\s+de\s+([a-z]+)/);
  if (m1 && MESES[m1[2]]) return toISO(ANIO_ACTUAL, MESES[m1[2]], m1[1]);
  const m2 = s.match(/([a-z]+)\s+(\d{1,2})/);
  if (m2 && MESES[m2[1]]) return toISO(ANIO_ACTUAL, MESES[m2[1]], m2[2]);
  return null;
};

const parseDiaSemana = (s) => {
  for (const [nombre, dow] of Object.entries(DIAS)) {
    if (new RegExp(`\\b${nombre}\\b`).test(s)) {
      const hoy = hoyISO();
      const hoyDow = new Date(hoy + 'T00:00:00Z').getUTCDay();
      const delta = (dow - hoyDow + 7) % 7;
      return addDays(hoy, delta);
    }
  }
  return null;
};

const parseRelativa = (s) => {
  if (/\bpasado\s+manana\b/.test(s)) return addDays(hoyISO(), 2);
  if (/\bmanana\b/.test(s)) return addDays(hoyISO(), 1);
  if (/\bhoy\b/.test(s)) return hoyISO();
  return null;
};

const parseFechaSimple = (s) =>
  parseISO(s) ??
  parseSlash(s) ??
  parseMesNombre(s) ??
  parseDiaSemana(s) ??
  parseRelativa(s);

// ---------- Parser de rangos ----------
const parseRango = (s) => {
  // PRIORIDAD 1: "del 15 al 17 de octubre" (mes compartido)
  const mesCompartido = s.match(
    /(?:del|desde\s+el|entre\s+el)\s+(\d{1,2})\s+(?:al|hasta\s+el|y\s+el?)\s+(\d{1,2})\s+de\s+([a-z]+)/
  );
  if (mesCompartido) {
    const mes = MESES[mesCompartido[3]];
    if (mes) {
      const f1 = toISO(ANIO_ACTUAL, mes, mesCompartido[1]);
      const f2 = toISO(ANIO_ACTUAL, mes, mesCompartido[2]);
      if (f1 && f2 && f2 > f1) {
        return { inicio: f1, fin: f2 };
      }
    }
  }

  // PRIORIDAD 2: patrones generales
  const patrones = [
    /del\s+(.+?)\s+al\s+(.+?)(?:\s*$|,|\.)/,
    /desde\s+(?:el\s+)?(.+?)\s+hasta\s+(?:el\s+)?(.+?)(?:\s*$|,|\.)/,
    /entre\s+(?:el\s+)?(.+?)\s+y\s+(?:el\s+)?(.+?)(?:\s*$|,|\.)/,
    /(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)\s+al\s+(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)/
  ];

  for (const p of patrones) {
    const m = s.match(p);
    if (m) {
      const f1 = parseFechaSimple(m[1]);
      const f2 = parseFechaSimple(m[2]);
      if (f1 && f2 && f2 > f1) {
        return { inicio: f1, fin: f2 };
      }
    }
  }
  return null;
};

// ---------- Duracion ----------
const parseDuracion = (s) => {
  const m = s.match(
    /por\s+(\d+|una|dos|tres|cuatro|cinco|seis|siete)\s+noches?/
  );
  if (!m) return null;
  const mapa = { una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7 };
  return mapa[m[1]] ?? parseInt(m[1], 10);
};

// ---------- Categoria ----------
const parseCategoria = (s) => {
  if (/\b(standard|std|estandar)\b/.test(s)) return 'STANDARD';
  if (/\b(superior|sup)\b/.test(s)) return 'SUPERIOR';
  if (/\b(premium|pre)\b/.test(s)) return 'PREMIUM';
  return null;
};

// ---------- Ocupacion ----------
const parseOcupacion = (s) => {
  let m = s.match(/(?:para|somos|seremos|vamos)\s+(\d{1,2})/);
  if (m) return parseInt(m[1], 10);

  m = s.match(/\b(una|dos|tres|cuatro|cinco|seis)\s+(?:persona|huesped)/);
  if (m) {
    const mapa = { una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6 };
    return mapa[m[1]] ?? null;
  }

  if (/\b(pareja|matrimonio)\b/.test(s)) return 2;
  if (/\b(solo yo|solo yo|para mi)\b/.test(s)) return 1;
  if (/\b(familia|en familia)\b/.test(s)) return 4;

  return null;
};

// ---------- Pasajero ----------
// Recibe el mensaje ORIGINAL (con mayusculas y tildes)
const parsePasajero = (s) => {
  // "a nombre de Juan Perez"
  let m = s.match(/a\s+nombre\s+de\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){0,3})/);
  if (m) return m[1].trim();

  // "soy Juan Perez" / "me llamo Juan Perez"
  m = s.match(/(?:soy|me\s+llamo)\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){0,3})/);
  if (m) return m[1].trim();

  // "mi nombre es Juan Perez"
  m = s.match(/mi\s+nombre\s+es\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){0,3})/);
  if (m) return m[1].trim();

  return null;
};

// ---------- Logica principal ----------
const out = {
  tipo: 'sin_fechas',
  fecha_inicio: null,
  fecha_fin: null,
  cantidad_noches: 0,
  categoria: parseCategoria(message),
  ocupacion: parseOcupacion(message) ?? 1,
  pasajero: parsePasajero(originalMessage)
};

const rango = parseRango(message);
const fechaSimple = parseFechaSimple(message);
const noches = parseDuracion(message);

if (rango) {
  out.tipo = 'rango';
  out.fecha_inicio = rango.inicio;
  out.fecha_fin = rango.fin;
  out.cantidad_noches = diffDays(rango.inicio, rango.fin);
} else if (fechaSimple) {
  const n = noches ?? 1;
  out.tipo = n > 1 ? 'desde_cantidad' : 'una_noche';
  out.fecha_inicio = fechaSimple;
  out.fecha_fin = n > 1 ? addDays(fechaSimple, n) : fechaSimple;
  out.cantidad_noches = n;
} else if (
  /\b(mes|semana|finde|fin de semana|verano|invierno|otono|primavera|octubre|noviembre|diciembre|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre)\b/.test(message)
) {
  out.tipo = 'ambigua';
}

return {
  json: {
    ...validado,
    payload: { fechas: out }
  }
};

const input = $json;

const approved = input.approved === true;

// Aceptar "response" (Disponibilidad) o "message" (Reserva)
const responseText = input.response ?? input.message ?? '';
const hasResponse = typeof responseText === 'string' && responseText.trim().length > 0;

const hasJudge = input.judge && typeof input.judge === 'object';

const valid = approved && hasResponse && hasJudge;

return [
  {
    json: {
      ...input,

      // Normalizar: siempre exponer "response"
      response: responseText || null,

      workerValidation: {
        valid,
        approved,
        hasResponse,
        hasJudge
      }
    }
  }
];

const input = $json;

// El Worker envía:
//   input.message  → mensaje original del huésped
//   input.response → respuesta generada por el Worker
//
// Prioridades:
//   - originalMessage: input.originalMessage (de Reserva/Facturación) o input.message
//   - message:         input.response (respuesta) o input.message (fallback)

const originalMsg = input.originalMessage ?? input.message ?? null;
const responseMsg = input.response ?? input.message ?? null;

return {
  json: {
    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    channel: input.channel,
    recipient: input.recipient ?? input.sender ?? null,

    originalMessage: originalMsg,
    message: responseMsg,

    approved: input.approved,

    esReclamoCobro: input.esReclamoCobro || false,
    esQueja: input.esQueja || false,
    reservaRegistrada: input.reservaRegistrada || null,

    worker: input.worker || null,
    judge: input.judge ?? null,

    dispatch: {
      ready: true,
      source: input.worker?.workflow ?? 'UNKNOWN'
    }
  }
};

const input = $json;

// Priorizar el motivo del escalation si existe
let motivo = 'El resultado del Worker no cumple con el contrato esperado.';

// Si el Worker mandó escalación con motivo, usarlo
if (input.escalation && input.escalation.reason) {
  motivo = input.escalation.reason;
}
// Si hay judge con reason, usarlo como fallback
else if (input.judge && input.judge.reason) {
  motivo = input.judge.reason;
}

return {
  json: {
    status: 'RECHAZADO',
    approved: false,
    response: null,

    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    error: {
      code: 'INVALID_WORKER_RESULT',
      message: 'El Manager recibió un resultado incompleto o no aprobado por el Worker.'
    },

    workerValidation: input.workerValidation ?? null,

    escalation: {
      required: true,
      reason: motivo
    },

    manager: {
      workflow: 'WF_MANAGER_ORQUESTADOR',
      stage: 'VALIDACION_RESULTADO_WORKER'
    }
  }
};

